import { test } from "node:test";
import assert from "node:assert/strict";
import { setImmediate as tick } from "node:timers/promises";
import { averageRating, teamDirectory } from "../src/hr/directory.ts";
import { makeLoaders, type Db, type Employee, type Office, type Review } from "../src/hr/repo.ts";

// Fake SQL client: answers the handful of queries the HR service sends and logs every round trip.
function fakeDb(employees: Employee[], offices: Office[], reviews: Review[]) {
    const log: string[] = [];
    const db: Db = {
        async query<T>(sql: string, params: unknown[]): Promise<T[]> {
            await tick();
            log.push(sql);
            const ids = params[0] as string[];
            if (sql.includes("FROM employees WHERE department_id")) {
                return employees.filter((e) => e.departmentId === params[0]).sort((a, b) => a.name.localeCompare(b.name)) as T[];
            }
            if (sql.includes("FROM employees WHERE id = ANY")) return employees.filter((e) => ids.includes(e.id)) as T[];
            if (sql.includes("FROM offices")) return offices.filter((o) => ids.includes(o.id)) as T[];
            if (sql.includes("FROM reviews")) {
                const latest = new Map<string, Review>();
                for (const r of reviews) if (ids.includes(r.employeeId) && (latest.get(r.employeeId)?.cycle ?? "") < r.cycle) latest.set(r.employeeId, r);
                return [...latest.values()] as T[];
            }
            throw new Error(`unexpected query: ${sql}`);
        },
    };
    return { db, log };
}

const offices: Office[] = [{ id: "lis", city: "Lisbon" }, { id: "ber", city: "Berlin" }];

function department(size: number) {
    const head: Employee = { id: "e0", name: "Amara Okafor", title: "Head of Platform", departmentId: "hq", managerId: null, officeId: "lis" };
    const team: Employee[] = Array.from({ length: size }, (_, i) => ({
        id: `p${i + 1}`,
        name: `Engineer ${String(i + 1).padStart(2, "0")}`,
        title: "Software Engineer",
        departmentId: "platform",
        managerId: i % 2 ? "e0" : "p1",
        officeId: i % 3 ? "ber" : "lis",
    }));
    const reviews: Review[] = team.flatMap((e, i) => [
        { employeeId: e.id, cycle: "2025-H2", rating: 3 },
        ...(i % 4 === 3 ? [] : [{ employeeId: e.id, cycle: "2026-H1", rating: ((i % 5) + 1) as Review["rating"] }]),
    ]);
    return fakeDb([head, ...team], offices, reviews);
}

test("the directory shows each person's manager, city and latest rating", async () => {
    const { db } = department(4);
    const rows = await teamDirectory(db, "platform");
    assert.deepEqual(rows.map((r) => [r.name, r.manager, r.city, r.lastRating]), [
        ["Engineer 01", "Engineer 01", "Lisbon", 1],
        ["Engineer 02", "Amara Okafor", "Berlin", 2],
        ["Engineer 03", "Engineer 01", "Berlin", 3],
        ["Engineer 04", "Amara Okafor", "Lisbon", 3],
    ]);
    assert.equal(averageRating(rows), 2.25);
});

test("a loader turns loads made together into one query and reuses results", async () => {
    const { db, log } = department(3);
    const loaders = makeLoaders(db);
    const [a, b, c] = await Promise.all([loaders.offices.load("lis"), loaders.offices.load("ber"), loaders.offices.load("lis")]);
    assert.deepEqual([a?.city, b?.city, c?.city], ["Lisbon", "Berlin", "Lisbon"]);
    assert.equal(await loaders.offices.load("mars"), null);
    assert.equal(log.length, 2);
});

test("a 40-person team page runs a fixed handful of queries", async () => {
    const { db, log } = department(40);
    const rows = await teamDirectory(db, "platform");
    assert.equal(rows.length, 40);
    console.log(`${log.length} queries for 40 employees; first few:`, log.slice(0, 5));
    assert.ok(log.length <= 4, `expected at most 4 queries, got ${log.length}`);
});

test("the number of queries doesn't grow with the size of the team", async () => {
    const small = department(5);
    const large = department(50);
    await teamDirectory(small.db, "platform");
    await teamDirectory(large.db, "platform");
    assert.equal(large.log.length, small.log.length);
});

test("people without a manager or a review yet still get a row", async () => {
    const { db } = fakeDb(
        [{ id: "x1", name: "Noor Haddad", title: "Founder", departmentId: "exec", managerId: null, officeId: "ber" }],
        offices,
        [],
    );
    const rows = await teamDirectory(db, "exec");
    assert.deepEqual(rows, [{ id: "x1", name: "Noor Haddad", title: "Founder", manager: null, city: "Berlin", lastRating: null }]);
    assert.equal(averageRating(rows), null);
});

test("an unknown department is an empty directory after a single query", async () => {
    const { db, log } = department(3);
    assert.deepEqual(await teamDirectory(db, "nope"), []);
    assert.equal(log.length, 1);
});
